-- Class Activity 3 · sample data for users and activity
-- Generated by generate_sample_data.py (seeded, reproducible).
-- 24 users, 135 events: pause 14, play 85, rate 16, search 20
-- Run AFTER ca3_tables.sql. Safe to run again: it clears both tables first.

BEGIN;

TRUNCATE activity, users RESTART IDENTITY;



-- Explicit ids were inserted, so move the identity counters past them.
SELECT setval(pg_get_serial_sequence('users', 'user_id'),        (SELECT max(user_id)     FROM users));
SELECT setval(pg_get_serial_sequence('activity', 'activity_id'), (SELECT max(activity_id) FROM activity));

COMMIT;

-- Self-check
SELECT (SELECT count(*) FROM users) AS users, (SELECT count(*) FROM activity) AS events;
SELECT events_data->>'type' AS event_type, count(*) FROM activity GROUP BY 1 ORDER BY 1;
